cards.solution:
function ambilUmur(data) {
  if (data.umur < 0) {
    throw new Error("Umur tidak valid");
  }
  return data.umur;
}
try {
  console.log(ambilUmur({ umur: -5 }));
} catch (error) {
  console.log(`Gagal: ${error.message}`);
}
